arguments.content:
:root {
  --primary: #1868DB;
  --primary-hover: #1251ab;
  --accent: #FF613D;
  --text-dark: #292A2E;
  --text-muted: #6B7280;
  --text-light: #9CA3AF;
  --bg-white: #FFFFFF;
  --bg-offwhite: #F9FAFB;
  --bg-gradient: linear-gradient(135deg, #f0f4ff 0%, #f9f5ff 100%);
  --border: #E5E7EB;
  --radius-sm: 6px;
  --radius: 12px;
  --radius-lg: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.05);
  --shadow-lg: 0 12px 24px rgba(0,0,0,0.1);
  --transition: all 0.2s ease;
  --max-width: 1200px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', sans-serif;
  color: var(--text-dark);
  background-color: var(--bg-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4, h5 {
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

h1 { font-size: 3.5rem; }
h2 { font-size: 2.5rem; }
h3 { font-size: 1.75rem; }
h4 { font-size: 1.25rem; }
p { margin-bottom: 16px; color: var(--text-muted); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  border: none;
  font-size: 1rem;
  text-align: center;
}

.btn-primary {
  background-color: var(--primary);
  color: var(--bg-white);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  transform: translateY(-1px);
}

.btn-secondary {
  background-color: transparent;
  color: var(--text-dark);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  background-color: var(--bg-offwhite);
}

.btn-accent {
  background-color: var(--accent);
  color: var(--bg-white);
}

/* Nav */
.navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 100;
  border-bottom: 1px solid var(--border);
}

.nav-brand {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}

.nav-links a {
  font-weight: 500;
  color: var(--text-muted);
  transition: var(--transition);
}

.nav-links a:hover {
  color: var(--text-dark);
}

.nav-actions {
  display: flex;
  gap: 16px;
  align-items: center;
}

/* Hero Section */
.hero {
  text-align: center;
  padding: 80px 0;
  background: var(--bg-gradient);
}

.hero h1 {
  max-width: 800px;
  margin: 0 auto 24px;
}

.hero p {
  font-size: 1.25rem;
  max-width: 600px;
  margin: 0 auto 32px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
}

/* Logo Bar */
.logo-bar {
  padding: 40px 0;
  text-align: center;
  border-bottom: 1px solid var(--border);
}

.logo-bar p {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
  margin-bottom: 24px;
}

.logos {
  display: flex;
  justify-content: center;
  gap: 40px;
  flex-wrap: wrap;
  opacity: 0.6;
}
.logos span {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text-muted);
}

/* Sections */
.section {
  padding: 80px 0;
}

.section-bg {
  background-color: var(--bg-offwhite);
}

/* Grid Layouts */
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* Cards */
.card {
  background: var(--bg-white);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  background: var(--bg-gradient);
  color: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 24px;
}

/* Feature Grid */
.features-grid .card {
  padding: 24px;
}

.features-grid h4 {
  margin-bottom: 8px;
  font-size: 1.1rem;
}

/* Use Cases */
.use-cases-list li {
  padding: 16px 0;
  border-bottom: 1px solid var(--border);
}
.use-cases-list li:last-child {
  border-bottom: none;
}

/* Testimonials */
.testimonial {
  background: var(--bg-gradient);
  border-radius: var(--radius);
  padding: 32px;
}
.testimonial p {
  font-size: 1.125rem;
  font-style: italic;
  color: var(--text-dark);
}
.testimonial-author {
  margin-top: 24px;
  font-weight: 600;
}

/* CTA Banner */
.cta-banner {
  background: var(--primary);
  color: var(--bg-white);
  text-align: center;
  padding: 80px 0;
  border-radius: var(--radius-lg);
  margin: 40px auto;
  max-width: var(--max-width);
}
.cta-banner h2 { margin-bottom: 24px; color: var(--bg-white); }
.cta-banner p { color: rgba(255,255,255,0.8); }

/* Pricing */
.pricing-header {
  text-align: center;
  margin-bottom: 48px;
}
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin: 24px 0;
}
.switch {
  position: relative;
  display: inline-block;
  width: 50px;
  height: 28px;
}
.switch input { opacity: 0; width: 0; height: 0; }
.slider {
  position: absolute;
  cursor: pointer;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: #ccc;
  transition: .4s;
  border-radius: 34px;
}
.slider:before {
  position: absolute;
  content: "";
  height: 20px;
  width: 20px;
  left: 4px;
  bottom: 4px;
  background-color: white;
  transition: .4s;
  border-radius: 50%;
}
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(22px); }

.badge {
  background: var(--accent);
  color: white;
  padding: 4px 8px;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 600;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.plan-card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  background: var(--bg-white);
  display: flex;
  flex-direction: column;
}
.plan-card.popular {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
  position: relative;
}
.plan-popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: 4px 12px;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 700;
}
.plan-name { font-size: 1.25rem; font-weight: 700; margin-bottom: 8px; }
.plan-price { font-size: 2.5rem; font-weight: 800; margin-bottom: 8px; }
.plan-price span { font-size: 1rem; color: var(--text-muted); font-weight: 400; }
.plan-features { margin: 24px 0; flex-grow: 1; }
.plan-features li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 12px;
  font-size: 0.875rem;
}
.plan-features i { color: var(--primary); margin-top: 2px; }

.comparison-table-wrap {
  overflow-x: auto;
  margin-top: 64px;
}
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}
.comparison-table th, .comparison-table td {
  padding: 16px;
  border-bottom: 1px solid var(--border);
}
.comparison-table th { font-weight: 600; background: var(--bg-offwhite); }

/* FAQ */
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 24px 0;
  background: none;
  border: none;
  font-size: 1.125rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-dark);
}
.faq-answer {
  padding-bottom: 24px;
  display: none;
  color: var(--text-muted);
}
.faq-item.active .faq-answer {
  display: block;
}
.faq-item.active .faq-question i {
  transform: rotate(180deg);
}

/* Auth Pages */
.auth-layout {
  min-height: 100vh;
  display: flex;
}
.auth-form-side {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 40px;
}
.auth-brand { margin-bottom: auto; }
.auth-form-container {
  max-width: 400px;
  width: 100%;
  margin: auto;
}
.auth-form-container h2 { margin-bottom: 8px; }
.auth-form-container > p { margin-bottom: 32px; }

.social-auth {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}
.btn-social {
  width: 100%;
  background: var(--bg-white);
  border: 1px solid var(--border);
  color: var(--text-dark);
  font-weight: 500;
  justify-content: center;
  gap: 8px;
}
.divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 24px 0;
  color: var(--text-light);
}
.divider::before, .divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--border);
}
.divider::before { margin-right: .25em; }
.divider::after { margin-left: .25em; }

.form-group {
  margin-bottom: 16px;
}
.form-group label {
  display: block;
  margin-bottom: 8px;
  font-size: 0.875rem;
  font-weight: 500;
}
.form-control {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 1rem;
}
.form-control:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1);
}

.auth-sidebar {
  flex: 1;
  background: var(--bg-gradient);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.auth-sidebar .testimonial {
  max-width: 480px;
  background: transparent;
}

/* Footer */
.footer {
  padding: 80px 0 40px;
  background: var(--text-dark);
  color: var(--bg-white);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}
.footer h4 {
  font-size: 1rem;
  margin-bottom: 16px;
  color: var(--bg-white);
}
.footer ul li {
  margin-bottom: 12px;
}
.footer ul a {
  color: #9CA3AF;
  font-size: 0.875rem;
  transition: var(--transition);
}
.footer ul a:hover {
  color: var(--bg-white);
}
.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #9CA3AF;
  font-size: 0.875rem;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  background: var(--text-dark);
  color: white;
  padding: 24px;
  border-radius: var(--radius);
  z-index: 1000;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: var(--shadow-lg);
  gap: 24px;
}
.cookie-banner-content { flex: 1; }
.cookie-banner-actions { display: flex; gap: 12px; }

.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 2000;
}
.modal-overlay.active { display: flex; }
.modal {
  background: var(--bg-white);
  padding: 32px;
  border-radius: var(--radius);
  max-width: 500px;
  width: 100%;
}
.modal h3 { margin-bottom: 16px; color: var(--text-dark); }
.preference-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  border-bottom: 1px solid var(--border);
  color: var(--text-dark);
}
.modal-actions {
  margin-top: 24px;
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

/* Utilities */
.text-center { text-align: center; }
.mt-8 { margin-top: 32px; }
.mb-8 { margin-bottom: 32px; }
.mb-4 { margin-bottom: 16px; }

@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4, .pricing-cards, .footer-grid {
    grid-template-columns: 1fr;
  }
  .auth-layout { flex-direction: column; }
  .cookie-banner { flex-direction: column; text-align: center; }
  h1 { font-size: 2.5rem; }
}

