input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(22px); }

.badge {
  background: var(--accent);
  color: white;
  padding: 4px 8px;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 600;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.plan-card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  background: var(--bg-white);
  display: flex;
  flex-direction: column;
}
.plan-card.popular {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
  position: relative;
}
.plan-popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: 4px 12px;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 700;
}
.plan-name { font-size: 1.25rem; font-weight: 700; margin-bottom: 8px; }
.plan-price { font-size: 2.5rem; font-weight: 800; margin-bottom: 8px; }
.plan-price span { font-size: 1rem; color: var(--text-muted); font-weight: 400; }
.plan-features { margin: 24px 0; flex-grow: 1; }
.plan-features li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 12px;
  font-size: 0.875rem;
}
.plan-features i { color: var(--primary); margin-top: 2px; }

.comparison-table-wrap {
  overflow-x: auto;
  margin-top: 64px;
}
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}
.comparison-table th, .comparison-table td {
  padding: 16px;
  border-bottom: 1px solid var(--border);
}
.comparison-table th { font-weight: 600; background: var(--bg-offwhite); }

/* FAQ */
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 24px 0;
  background: none;
  border: none;
  font-size: 1.125rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-dark);
}
.faq-answer {
  padding-bottom: 24px;
  display: none;
  color: var(--text-muted);
}
.faq-item.active .faq-answer {
  display: block;
}
.faq-item.active .faq-question i {
  transform: rotate(180deg);
}

/* Auth Pages */
.auth-layout {
  min-height: 100vh;
  display: flex;
}
.auth-form-side {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 40px;
}
.auth-brand { margin-bottom: auto; }
.auth-form-container {
  max-width: 400px;
  width: 100%;
  margin: auto;
}
.auth-form-container h2 { margin-bottom: 8px; }
.auth-form-container > p { margin-bottom: 32px; }

.social-auth {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}
.btn-social {
  width: 100%;
  background: var(--bg-white);
  border: 1px solid var(--border);
  color: var(--text-dark);
  font-weight: 500;
  justify-content: center;
  gap: 8px;
}
.divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 24px 0;
  color: var(--text-light);
}
.divider::before, .divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--border);
}
.divider::before { margin-right: .25em; }
.divider::after { margin-left: .25em; }

.form-group {
  margin-bottom: 16px;
}
.form-group label {
  display: block;
  margin-bottom: 8px;
  font-size: 0.875rem;
  font-weight: 500;
}
.form-control {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 1rem;
}
.form-control:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1);
}

.auth-sidebar {
  flex: 1;
  background: var(--bg-gradient);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.auth-sidebar .testimonial {
  max-width: 480px;
  background: transparent;
}

/* Footer */
.footer {
  padding: 80px 0 40px;
  background: var(--text-dark);
  color: var(--bg-white);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}
.footer h4 {
  font-size: 1rem;
  margin-bottom: 16px;
  color: var(--bg-white);
}
.footer ul li {
  margin-bottom: 12px;
}
.footer ul a {
  color: #9CA3AF;
  font-size: 0.875rem;
  transition: var(--transition);
}
.footer ul a:hover {
  color: var(--bg-white);
}
.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #9CA3AF;
  font-size: 0.875rem;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  background: var(--text-dark);
  color: white;
  padding: 24px;
  border-radius: var(--radius);
  z-index: 1000;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: var(--shadow-lg);
  gap: 24px;
}
.cookie-banner-content { flex: 1; }
.cookie-banner-actions { display: flex; gap: 12px; }

.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 2000;
}
.modal-overlay.active { display: flex; }
.modal {
  background: var(--bg-white);
  padding: 32px;
  border-radius: var(--radius);
  max-width: 500px;
  width: 100%;
}
.modal h3 { margin-bottom: 16px; color: var(--text-dark); }
.preference-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  border-bottom: 1px solid var(--border);
  color: var(--text-dark);
}
.modal-actions {
  margin-top: 24px;
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

/* Utilities */
.text-center { text-align: center; }
.mt-8 { margin-top: 32px; }
.mb-8 { margin-bottom: 32px; }
.mb-4 { margin-bottom: 16px; }

@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4, .pricing-cards, .footer-grid {
    grid-template-columns: 1fr;
  }
  .auth-layout { flex-direction: column; }
  .cookie-banner { flex-direction: column; text-align: center; }
  h1 { font-size: 2.5rem; }
}

document.addEventListener('DOMContentLoaded', () => {

  // Cookie Consent Banner
  const cookieBanner = document.getElementById('cookie-consent-banner');
  const acceptCookiesBtn = document.getElementById('accept-cookies');
  const rejectCookiesBtn = document.getElementById('reject-cookies');
  const managePrefsBtn = document.getElementById('manage-preferences');
  const cookieModal = document.getElementById('cookie-modal');
  const savePrefsBtn = document.getElementById('save-preferences');

  if (cookieBanner) {
    if (!localStorage.getItem('cookieConsent')) {
      cookieBanner.style.display = 'flex';
    } else {
      cookieBanner.style.display = 'none';
    }

    if (acceptCookiesBtn) {
      acceptCookiesBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'accepted');
        cookieBanner.style.display = 'none';
      });
    }

    if (rejectCookiesBtn) {
      rejectCookiesBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'rejected');
        cookieBanner.style.display = 'none';
      });
    }

    if (managePrefsBtn && cookieModal) {
      managePrefsBtn.addEventListener('click', () => {
        cookieModal.classList.add('active');
      });
    }

    if (savePrefsBtn) {
      savePrefsBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'custom');
        cookieModal.classList.remove('active');
        cookieBanner.style.display = 'none';
      });
    }
  }

  // Pricing Toggle (Monthly / Annually)
  const billingToggle = document.getElementById('billing-toggle');
  if (billingToggle) {
    billingToggle.addEventListener('change', (e) => {
      const isAnnual = e.target.checked;
      const prices = document.querySelectorAll('.dynamic-price');
      prices.forEach(priceEl => {
        const monthly = priceEl.getAttribute('data-monthly');
        const annual = priceEl.getAttribute('data-annual');
        if (monthly !== null && annual !== null) {
          priceEl.innerHTML = `\$${isAnnual ? annual : monthly}<span>/user/mo</span>`;
        }
      });
    });
  }

  // Pricing Team Size Slider
  const teamSlider = document.getElementById('team-size-slider');
  const teamSizeDisplay = document.getElementById('team-size-display');
  if (teamSlider && teamSizeDisplay) {
    teamSlider.addEventListener('input', (e) => {
      teamSizeDisplay.textContent = e.target.value;
      // Could add logic to highlight a plan based on value
    });
  }

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    if (question) {
      question.addEventListener('click', () => {
        const isActive = item.classList.contains('active');
        // Close all
        faqItems.forEach(faq => faq.classList.remove('active'));
        if (!isActive) {
          item.classList.add('active');
        }
      });
    }
  });

  // Comparison Table Expand
  const expandBtns = document.querySelectorAll('.expand-features-btn');
  const comparisonTableWrap = document.querySelector('.comparison-table-wrap');
  if (expandBtns.length > 0 && comparisonTableWrap) {
    expandBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        comparisonTableWrap.scrollIntoView({ behavior: 'smooth' });
        // Can add blinking or highlighting to the table
      });
    });
  }

  // Forms
  const loginForm = document.getElementById('login-form');
  if (loginForm) {
    loginForm.addEventListener('submit', (e) => {
      e.preventDefault();
      // Proceed to email auth flow mock
      alert('Proceeding to authentication...');
    });
  }

  const signupForm = document.getElementById('signup-form');
  if (signupForm) {
    signupForm.addEventListener('submit', (e) => {
      e.preventDefault();
      // Proceed to signup flow mock
      alert('Proceeding to account creation...');
    });
  }

});

